SELECT q.*,z.name zone_name,CASE WHEN z.active_yn='Y' AND z.deleted_at IS NULL THEN 'Y' ELSE 'N' END zone_active_yn,
u.display_name created_by_name FROM () q
LEFT JOIN farm_zone z ON z.id=q.zone_id LEFT JOIN users u ON u.id=q.created_by
WHERE q.farm_id=#{farmId} AND q.record_date >=#{dateFrom}
 AND q.record_date <=#{dateTo} AND q.zone_id=#{zoneId}
 AND q.created_by=#{createdBy}
AND q.record_type IN #{t}
ORDER BY ${orderBy} ${direction},q.id ${direction},q.record_type ${direction} LIMIT #{size} OFFSET #{offset}

